contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // depositAmount must be available in this contract's balance to send
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0, "need positive deposit");
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // record C's balance before deposit
        uint cBalanceBeforeDeposit = address(c).balance;

        // perform the deposit of exactly depositAmount
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // record C's balance immediately after deposit
        uint cBalanceAfterDeposit = address(c).balance;

        // attempt withdrawAll and record whether it reverted and post-call balance
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint cBalanceAfterWithdraw = address(c).balance;

        // If withdrawAll succeeded then C's balance should not decrease by more than the prior depositAmount.
        // i.e., (cBalanceAfterDeposit - cBalanceAfterWithdraw) <= depositAmount
        // If it reverted then no guarantee about change, so allow any behavior; include reverted in condition.
        assert(reverted || (cBalanceAfterDeposit >= cBalanceAfterWithdraw && (cBalanceAfterDeposit - cBalanceAfterWithdraw) <= depositAmount));
    }

    // allow receiving Ether from C
    receive() external payable {}
}

